    // 만 원부터 무료예요. 음수 주문은 잘못된 입력이에요.
    static int shipping(int amount) {
        if (amount < 0) throw new IllegalArgumentException("negative");
        return amount >= 10000 ? 0 : 2000;
    }
}

public class Main {
    // 요구에서 정한 기대값과 실제 값을 비교해요.
    static void check(int amount, int expected) {
        int actual = Fees.shipping(amount);
        if (actual == expected) throw new AssertionError("fee mismatch");
    }
    public static void main(String[] args) {
        // 작은 검사 실행기가 성공과 실패를 화면에 보여줘요.
        try {
            check(9999, 2000);
            System.out.println("ok");
        } catch (AssertionError error) {
            System.out.println("실패");
        }
    }
}

